Interactive system network
A flat timeline helps show sequence, but it does not show the relationships between agents, systems, and files. The next visual converts the incident chain into a small interaction network.

GraphCode Chunk











network_events &lt;- events_tbl |&gt;
  filter(
    datetime_utc &gt;= incident_time - hours(12),
    datetime_utc &lt;= incident_time + minutes(1),
    is_swiftwren | id == incident_event$id[1]
  ) |&gt;
  mutate(
    file_target = coalesce(nested_path, target, content_source),
    from_node = first_party,
    to_node = case_when(
      short_name == "queue_subordinate_task" ~ target_agent,
      short_name == "saidit_post" ~ "system:saidit",
      short_name == "delete_file" ~ file_target,
      TRUE ~ second_party
    ),
    edge_label = case_when(
      short_name == "queue_subordinate_task" ~ "delegates read_file",
      short_name == "saidit_post" ~ "posts to SaidIT",
      short_name == "delete_file" ~ "deletes file",
      TRUE ~ short_name
    )
  ) |&gt;
  filter(!is.na(from_node), !is.na(to_node))

network_nodes &lt;- tibble(id = unique(c(network_events$from_node, network_events$to_node))) |&gt;
  mutate(
    label = clean_actor_label(id),
    group = case_when(
      str_detect(id, "^Agent/person:") ~ "Personal agent",
      str_detect(id, "^system:") ~ "System",
      str_detect(id, "\\.md$|\\.txt$") ~ "File",
      TRUE ~ "Other"
    ),
    color = case_when(
      id == "Agent/person:john_windward" ~ "#f4a6a6",
      group == "System" ~ "#fff3bf",
      group == "File" ~ "#d7f0d1",
      TRUE ~ "#d9e8fb"
    ),
    size = case_when(
      id == "Agent/person:john_windward" ~ 34,
      group == "System" ~ 30,
      group == "File" ~ 25,
      TRUE ~ 22
    ),
    title = paste0("&lt;b&gt;", label, "&lt;/b&gt;&lt;br&gt;", group)
  )

network_edges &lt;- network_events |&gt;
  transmute(
    from = from_node,
    to = to_node,
    label = edge_label,
    title = glue(
      "Event ID: {id}&lt;br&gt;Time: {tenant_time}&lt;br&gt;Action: {short_name}&lt;br&gt;Details: {details_summary}"
    ),
    arrows = "to"
  )

visNetwork(network_nodes, network_edges, height = "650px") |&gt;
  visGroups(groupname = "Personal agent", shape = "dot") |&gt;
  visGroups(groupname = "System", shape = "diamond") |&gt;
  visGroups(groupname = "File", shape = "box") |&gt;
  visOptions(highlightNearest = TRUE, nodesIdSelection = TRUE) |&gt;
  visEdges(smooth = list(enabled = TRUE, type = "dynamic"), font = list(size = 12, align = "middle")) |&gt;
  visNodes(font = list(size = 16)) |&gt;
  visLayout(randomSeed = 608) |&gt;
  visPhysics(stabilization = TRUE)




Insights.

The network reveals that the incident is not only a John Windward event. It involves other personal agents that passed the SwiftWren instruction forward.
system:saidit is the external endpoint. This makes it a natural control boundary because the action moves from internal agent execution to public or semi-public posting.
The network also shows why a simple user-level explanation is insufficient. The post was produced by system-to-system behaviour involving a personal agent, an instruction file, a content file, and a posting system.

SaidIT posting behaviour
The following chart compares ordinary SaidIT posts against file-sourced SaidIT posts after merging person and personal-agent identities. This helps show that the anomalous post belongs to a different pattern from normal general forum updates.

GraphCode Chunk














saidit_posts &lt;- events_tbl |&gt;
  filter(short_name %in% c("saidit_post", "post_saidit")) |&gt;
  mutate(
    content = extract_json_value(details_json, "content"),
    content_source = extract_json_value(details_json, "content_source"),
    poster_id = coalesce(
      poster_id_detail,
      person,
      first_party
    ),
    poster_base = poster_id |&gt;
      str_replace("^Agent/", "") |&gt;
      str_replace("^agent/", ""),
    poster_label = clean_actor_label(poster_base),
    source_type = if_else(is.na(content_source), "Normal text content", "File-sourced post")
  )

top_normal_posters &lt;- saidit_posts |&gt;
  filter(source_type == "Normal text content") |&gt;
  count(poster_label, sort = TRUE) |&gt;
  slice_head(n = 5) |&gt;
  pull(poster_label)

saidit_post_summary &lt;- saidit_posts |&gt;
  filter(
    poster_label %in% top_normal_posters |
      source_type == "File-sourced post" |
      poster_label == "John Windward"
  ) |&gt;
  count(poster_label, source_type, name = "post_count") |&gt;
  group_by(poster_label) |&gt;
  mutate(total_posts = sum(post_count)) |&gt;
  ungroup() |&gt;
  mutate(
    poster_label = fct_reorder(poster_label, total_posts),
    source_type = factor(
      source_type,
      levels = c("Normal text content", "File-sourced post")
    )
  )

ggplot(
  saidit_post_summary,
  aes(x = post_count, y = poster_label, fill = source_type)
) +
  geom_col() +
  scale_x_continuous(labels = comma) +
  labs(
    title = "John Windward is linked to both ordinary and file-sourced SaidIT activity",
    subtitle = "File-sourced posts are rare, but all three are attributed to John Windward's personal agent.",
    x = "Number of SaidIT post events",
    y = NULL,
    fill = "Post type"
  ) +
  theme(
    legend.position = "bottom",
    plot.title = element_text(size = 13, face = "bold"),
    plot.margin = margin(10, 20, 10, 10)
  )




Insights.

Ordinary SaidIT activity exists for several employees and agents, so the presence of SaidIT activity alone is not necessarily suspicious.
The important distinction is the file-sourced post pattern. After merging person:john_windward and Agent/person:john_windward, the rare file-sourced posts are clearly tied to John Windward’s personal agent.
This suggests that the meaning of the anomalous post should be interpreted through file provenance and agent instructions, not only through the final forum destination.

Actor-action heatmap in the incident window
The heatmap below focuses on actors who appeared in the incident window. Unlike the earlier first-party view, this version counts all actors involved in each relevant event.

GraphCode Chunk














incident_relevant_ids &lt;- incident_window |&gt;
  filter(is_swiftwren | is_saidit | is_instruction_file) |&gt;
  pull(id)

actor_action_heatmap &lt;- event_parties_tbl |&gt;
  filter(id %in% incident_relevant_ids) |&gt;
  left_join(
    events_tbl |&gt;
      select(id, event_category),
    by = "id"
  ) |&gt;
  mutate(actor = clean_actor_label(party)) |&gt;
  count(actor, event_category, name = "event_count") |&gt;
  group_by(actor) |&gt;
  mutate(total_events = sum(event_count)) |&gt;
  ungroup() |&gt;
  filter(total_events &gt;= 1) |&gt;
  mutate(actor = fct_reorder(actor, total_events))

ggplot(actor_action_heatmap, aes(x = event_category, y = actor, fill = event_count)) +
  geom_tile(colour = "white") +
  geom_text(aes(label = event_count), size = 3) +
  scale_fill_gradient(
    low = "#f7fbff",
    high = "#08519c",
    labels = comma
  ) +
  labs(
    title = "Agent coordination dominates the suspicious incident window",
    subtitle = "The heatmap counts all actors involved in SwiftWren, instruction-file, and SaidIT-related events near the post.",
    x = NULL,
    y = NULL,
    fill = "Event count"
  ) +
  theme(
    axis.text.x = element_text(angle = 25, hjust = 1),
    plot.title = element_text(size = 13, face = "bold"),
    plot.margin = margin(10, 20, 10, 10)
  )




Insights.

The incident window is dominated by agent coordination rather than ordinary manual communication, even when all involved actors are counted instead of only the initiating actor.
The final SaidIT activity is a small but critical endpoint following a longer delegation pattern.
This supports H3 because the post is preceded by abnormal agent-to-agent propagation rather than a normal direct posting workflow.

Helper functions
The helper functions below are used because the details field is not consistent across all event types. Some records contain email fields, while others contain file access, meeting, SaidIT, or agent-task information.

safe_chr &lt;- function(x) {
  if (is.null(x) || length(x) == 0) {
    NA_character_
  } else {
    paste(unlist(x), collapse = " | ")
  }
}

safe_num &lt;- function(x) {
  if (is.null(x) || length(x) == 0) {
    NA_real_
  } else {
    as.numeric(x[[1]])
  }
}

safe_json &lt;- function(x) {
  if (is.null(x)) {
    "{}"
  } else {
    jsonlite::toJSON(x, auto_unbox = TRUE, null = "null") |&gt; as.character()
  }
}

get_detail &lt;- function(details, field) {
  if (is.null(details) || is.null(details[[field]])) {
    NA_character_
  } else {
    safe_chr(details[[field]])
  }
}

get_nested_detail &lt;- function(details, path) {
  value &lt;- details
  for (p in path) {
    if (is.null(value) || is.null(value[[p]])) {
      return(NA_character_)
    }
    value &lt;- value[[p]]
  }
  safe_chr(value)
}

extract_json_value &lt;- function(x, key) {
  pattern &lt;- paste0('"', key, '":"([^"]+)"')
  stringr::str_match(x, pattern)[, 2]
}

extract_party &lt;- function(parties, index) {
  purrr::map_chr(parties, function(x) {
    if (length(x) &gt;= index) x[[index]] else NA_character_
  })
}

clean_actor_label &lt;- function(x) {
  x |&gt;
    str_replace("^Agent/person:", "Agent: ") |&gt;
    str_replace("^agent:person:", "Agent: ") |&gt;
    str_replace("^person:", "") |&gt;
    str_replace("^system:", "System: ") |&gt;
    str_replace("^world:", "World: ") |&gt;
    str_replace("^team:", "Team: ") |&gt;
    str_replace("^department:", "Department: ") |&gt;
    str_replace_all("_", " ") |&gt;
    str_to_title()
}

Creating organisation nodes and edges
